from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def build_tree(vals):
    if not vals or vals[0] is None:
        return None
    root = TreeNode(vals[0])
    q = deque([root])
    i = 1
    while q and i < len(vals):
        node = q.popleft()
        if i < len(vals) and vals[i] is not None:
            node.left = TreeNode(vals[i])
            q.append(node.left)
        i += 1
        if i < len(vals) and vals[i] is not None:
            node.right = TreeNode(vals[i])
            q.append(node.right)
        i += 1
    return root


def tree_to_level(root):
    out, q = [], deque([root])
    while q:
        node = q.popleft()
        if node:
            out.append(node.val)
            q.append(node.left)
            q.append(node.right)
        else:
            out.append(None)
    while out and out[-1] is None:
        out.pop()
    return out


def parse_tree():
    return build_tree([None if t == "null" else int(t) for t in input().split()])


def fmt_level(root):
    return " ".join("null" if v is None else str(v) for v in tree_to_level(root))

class Solution:
    def sortedArrayToBST(self, nums):
        def build(l, r):
            if l > r:
                return None
            m = (l + r) // 2
            return TreeNode(nums[m], build(l, m - 1), build(m + 1, r))
        return build(0, len(nums) - 1)

if __name__ == "__main__":
    root = Solution().sortedArrayToBST([-10, -3, 0, 5, 9])
    print(tree_to_level(root))   # [0, -10, 5, None, -3, None, 9]

